// Frappe Website Script: Hide Cart and More menu items until user is logged in
// Add this to: Website Settings > Website Script

frappe.ready(function() {

  // Check if user is logged in
  function isUserLoggedIn() {
    // Frappe sets frappe.session.user to 'Guest' when not logged in
    return frappe.session.user && frappe.session.user !== 'Guest';
  }

  // Function to hide protected menu items
  function hideProtectedMenuItems() {
    // Target only the dropdown items, not parent menu items

    // Hide Cart dropdown item (inside Webshop dropdown)
    $('.dropdown-menu .dropdown-item').each(function() {
      var text = $(this).text().trim();
      if (text === 'Cart') {
        $(this).hide();
      }
    });

    // Hide More menu item (top level navbar item)
    $('.navbar-nav > li').each(function() {
      var linkText = $(this).find('> a').text().trim();
      if (linkText === 'More') {
        $(this).hide();
      }
    });

    // Alternative: Hide by specific href if Cart has its own direct link
    $('.navbar-nav a[href$="/cart"]').parent('li').hide();

    // Mark hidden items for tracking
    $('.dropdown-menu .dropdown-item').each(function() {
      if ($(this).text().trim() === 'Cart' && $(this).is(':hidden')) {
        $(this).attr('data-auth-hidden', 'true');
      }
    });

    $('.navbar-nav > li').each(function() {
      if ($(this).find('> a').text().trim() === 'More' && $(this).is(':hidden')) {
        $(this).attr('data-auth-hidden', 'true');
      }
    });
  }

  // Function to show protected menu items
  function showProtectedMenuItems() {
    // Show items that were hidden by this script
    $('[data-auth-hidden="true"]').show().removeAttr('data-auth-hidden');
  }

  // Main logic
  if (!isUserLoggedIn()) {
    // Hide menu items if user is not logged in
    hideProtectedMenuItems();

    // Also hide after any dynamic content loads
    $(document).on('page-change', function() {
      if (!isUserLoggedIn()) {
        setTimeout(hideProtectedMenuItems, 100);
      }
    });

    // Handle dynamic dropdowns
    $('.navbar-nav .dropdown-toggle').on('click', function() {
      if (!isUserLoggedIn()) {
        setTimeout(hideProtectedMenuItems, 50);
      }
    });
  } else {
    // Show menu items if user is logged in
    showProtectedMenuItems();
  }

  // Listen for login events
  $(document).on('user-logged-in', function() {
    showProtectedMenuItems();
  });

});
